//! Generated tonic / prost bindings for LlamaForge gRPC services.
//!
//! Implements design.md §7.0 (Protocol Buffers Definition) and §7.1
//! (gRPC Streaming: Chat Completion — primary API). Wire format
//! source-of-truth lives under `proto/`; this crate is regenerated by
//! `build.rs`.

pub mod inference {
    tonic::include_proto!("llamaforge.inference");
}

pub mod management {
    tonic::include_proto!("llamaforge.management");
}
